class Node {
  constructor(char, freq, left = null, right = null) {
    this.char = char;
    this.freq = freq;
    this.left = left;
    this.right = right;
  }
}

function huffman(freqs) {
  let nodes = Object.entries(freqs).map(([char, freq]) => new Node(char, freq));
  while (nodes.length > 1) {
    nodes.sort((a, b) => a.freq - b.freq);
    const left = nodes.shift();
    const right = nodes.shift();
    nodes.push(new Node(null, left.freq + right.freq, left, right));
  }
  const codes = {};
  const assign = (node, code) => {
    if (!node) return;
    if (node.char !== null) { codes[node.char] = code || '0'; return; }
    assign(node.left, code + '0');
    assign(node.right, code + '1');
  };
  assign(nodes[0], '');
  return codes;
}

